# Restore and execute the exact locally validated Spirit Shrine generator.
# Python standard library only. No external downloads or game boot.
import base64, gzip, hashlib, json, runpy
from pathlib import Path
here = Path(__file__).resolve().parent
source = gzip.decompress(base64.b64decode("""""", validate=True))
assert hashlib.sha256(source).hexdigest() == "2825bfb059e26cc541a0da014f64547a69cfd738c530340bf9cfa5b180f09318", "source mismatch"
script = here / "build_shrine.py"
if script.exists() and script.read_bytes() != source:
    raise RuntimeError("Existing build_shrine.py differs; preserve manual edits before rebuilding")
script.write_bytes(source)
runpy.run_path(str(script), run_name="__main__")
raw = gzip.decompress((here / "prefab-extension/spirit_shrine.nbt").read_bytes())
assert hashlib.sha256(raw).hexdigest() == "6eb8b1072af1e688d9185652d3d3c08c4f51932b14e08072eddbc55b6be0fdbd", "raw NBT mismatch"
